import React, { FunctionComponent, ReactNode, useEffect, useState } from 'react'
import styled from '@emotion/styled'
import { navigate } from 'gatsby'
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome'
import { faMoon, faSun } from '@fortawesome/free-solid-svg-icons'
import { c, bp } from 'styles/theme'

const Container = styled.div`
  min-height: 100vh;
  background: ${c.bg};
`

const Header = styled.header`
  background: ${c.bg};
  border-bottom: 1px solid ${c.border};
  position: sticky;
  top: 0;
  z-index: 100;
`

const HeaderContent = styled.div`
  max-width: 840px;
  margin: 0 auto;
  padding: 0 32px;
  display: flex;
  align-items: center;
  height: 60px;
  gap: 16px;

  ${bp.md} {
    padding: 0 16px;
    height: 54px;
  }
`

const Logo = styled.button`
  font-size: 19px;
  font-weight: 700;
  color: ${c.text};
  background: none;
  border: none;
  padding: 0;
  cursor: pointer;
  font-family: inherit;
  flex-shrink: 0;

  span {
    color: ${c.primary};
  }
`

const Crumb = styled.span`
  font-size: 14px;
  color: ${c.textMuted};
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;

  ${bp.sm} {
    display: none;
  }
`

const Actions = styled.div`
  display: flex;
  align-items: center;
  gap: 8px;
  margin-left: auto;
`

const IconButton = styled.button`
  display: flex;
  align-items: center;
  justify-content: center;
  width: 36px;
  height: 36px;
  border: 1px solid ${c.border};
  border-radius: 8px;
  background: ${c.bgSubtle};
  color: ${c.textMuted};
  font-size: 14px;
  cursor: pointer;
  transition: all 0.2s ease;
  flex-shrink: 0;

  &:hover {
    background: ${c.bgMuted};
    color: ${c.text};
    border-color: ${c.primary};
  }

  ${bp.md} {
    width: 32px;
    height: 32px;
  }
`

const BlogButton = styled.button`
  background: ${c.bgSubtle};
  border: 1px solid ${c.border};
  border-radius: 8px;
  padding: 8px 14px;
  font-size: 13px;
  font-weight: 600;
  color: ${c.text};
  cursor: pointer;
  font-family: inherit;
  transition: all 0.2s ease;
  flex-shrink: 0;

  &:hover {
    border-color: ${c.primary};
    color: ${c.primary};
  }

  ${bp.md} {
    padding: 6px 10px;
    font-size: 12px;
  }
`

const Main = styled.main`
  max-width: 840px;
  margin: 0 auto;
  padding: 32px 32px 96px;

  ${bp.md} {
    padding: 20px 16px 96px;
  }
`

type QuizChromeProps = {
  crumb?: string
  children: ReactNode
}

/** 퀴즈 3개 페이지가 공유하는 헤더와 본문 컨테이너 */
const QuizChrome: FunctionComponent<QuizChromeProps> = function ({
  crumb,
  children,
}) {
  const [isDark, setIsDark] = useState(false)

  useEffect(() => {
    setIsDark(document.documentElement.getAttribute('data-theme') === 'dark')
  }, [])

  const toggleTheme = () => {
    const next = isDark ? 'light' : 'dark'
    document.documentElement.setAttribute('data-theme', next)
    localStorage.setItem('theme', next)
    setIsDark(!isDark)
  }

  return (
    <Container>
      <Header>
        <HeaderContent>
          <Logo onClick={() => navigate('/')}>
            <span>don</span>tech
          </Logo>
          {crumb && <Crumb>{crumb}</Crumb>}
          <Actions>
            <IconButton onClick={toggleTheme} aria-label="테마 전환">
              <FontAwesomeIcon icon={isDark ? faSun : faMoon} />
            </IconButton>
            <BlogButton onClick={() => navigate('/')}>블로그로</BlogButton>
          </Actions>
        </HeaderContent>
      </Header>
      <Main>{children}</Main>
    </Container>
  )
}

export default QuizChrome
